const $ = (sel) => document.querySelector(sel);

// --- Polytonic helpers (very approximate) ---
const combining = {
  acute: "\u0301",
  grave: "\u0300",
  circumflex: "\u0342",
  diaeresis: "\u0308",
  smooth: "\u0313",
  rough: "\u0314",
  iotaSub: "\u0345",
};

function nfd(s){ return s.normalize('NFD'); }
function nfc(s){ return s.normalize('NFC'); }

function stripAccentsKeepDiaeresis(s){
  // Remove accent marks & breathings; keep diaeresis (helps syllable splitting sometimes)
  const drop = new Set([
    combining.acute, combining.grave, combining.circumflex,
    combining.smooth, combining.rough, combining.iotaSub
  ]);
  return nfc(nfd(s).split('').filter(ch => !drop.has(ch)).join(''));
}

function stripAllDiacritics(s){
  // Remove all combining marks
  return nfc(nfd(s).replace(/\p{M}+/gu, ''));
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function tokenizeGreekWords(text){
  // Keep Greek words; ignore punctuation; allow spaces.
  const parts = text.split(/\s+/).filter(Boolean);
  return parts.map(p => p.replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'')).filter(Boolean);
}

const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);

function lowerGreek(s){
  // Lowercase with Greek-aware mapping
  return s.toLocaleLowerCase('el');
}

function hasDiaeresisOnIotaOrUpsilon(word){
  // detect ϊ, ϋ (either precomposed or combining)
  const w = nfd(word);
  return /[ιυΙΥ][\u0308]/.test(w) || /[ϊϋΪΫ]/.test(word);
}

function syllabifyRough(word){
  // Very rough syllable guess: count vowel nuclei, treating common diphthongs as one nucleus
  // unless diaeresis breaks them.
  const w0 = stripAccentsKeepDiaeresis(word);
  const w = lowerGreek(w0);

  // Build a simplified stream of letters (keep diaeresis as marker)
  const chars = Array.from(nfd(w));

  // Helper: check if char is vowel base
  const isVowelBase = (c) => vowels.has(c);

  // Determine if a vowel has diaeresis
  const hasDia = (i) => {
    // look ahead for combining diaeresis
    return chars[i+1] === combining.diaeresis;
  };

  // Common diphthongs
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ']);

  let nuclei = [];
  for(let i=0;i<chars.length;i++){
    const c = chars[i];
    if(!isGreekLetter(c) && c !== combining.diaeresis) continue;

    if(isVowelBase(c)){
      // if diaeresis, force single-vowel nucleus
      if(hasDia(i)){
        nuclei.push({start:i, end:i});
        continue;
      }
      // try diphthong with next vowel base (skipping combining marks)
      let j = i+1;
      // skip combining marks (except diaeresis which would have been caught)
      while(j < chars.length && /\p{M}/u.test(chars[j])) j++;
      if(j < chars.length && isVowelBase(chars[j])){
        // if next vowel has diaeresis, do not form diphthong
        if(hasDia(j)){
          nuclei.push({start:i, end:i});
        } else {
          const pair = c + chars[j];
          if(diph.has(pair)){
            nuclei.push({start:i, end:j});
            i = j; // consume
          } else {
            nuclei.push({start:i, end:i});
          }
        }
      } else {
        nuclei.push({start:i, end:i});
      }
    }
  }

  // Create a naive syllable segmentation by cutting before each nucleus (except first)
  // This is not real Greek syllabification; it's just for a visual cue.
  const base = Array.from(w0); // NFC-ish
  // Map approximate nucleus positions from NFD indices to NFC indices is hard; instead, just return nuclei count.
  return {count: nuclei.length};
}

function endsWithNormalized(word, ending){
  const w = lowerGreek(stripAllDiacritics(word));
  return w.endsWith(ending);
}

function placeAcute(word, positionFromEnd){
  // positionFromEnd: 1=ultima, 2=penult, 3=antepenult
  // Place an acute on the first vowel of the target syllable nucleus (approx by counting vowel nuclei from end).
  const wNFD = nfd(stripAccentsKeepDiaeresis(word));
  const chars = Array.from(wNFD);

  const isVowelBase = (c) => vowels.has(c);
  const hasDia = (i) => chars[i+1] === combining.diaeresis;
  const diph = new Set(['αι','ει','οι','υι','αυ','ευ','ηυ','ου','ωυ']);

  // Find nuclei indices (start index of nucleus)
  let nucleiStarts = [];
  for(let i=0;i<chars.length;i++){
    const c = chars[i];
    if(isVowelBase(c)){
      if(hasDia(i)){
        nucleiStarts.push(i);
        continue;
      }
      let j = i+1;
      while(j < chars.length && /\p{M}/u.test(chars[j])) j++;
      if(j < chars.length && isVowelBase(chars[j]) && !hasDia(j)){
        const pair = c + chars[j];
        if(diph.has(pair)){
          nucleiStarts.push(i);
          i = j;
        } else {
          nucleiStarts.push(i);
        }
      } else {
        nucleiStarts.push(i);
      }
    }
  }

  if(nucleiStarts.length === 0) return word;
  const idxFromEnd = nucleiStarts.length - positionFromEnd;
  const nucleusStart = nucleiStarts[Math.max(0, idxFromEnd)];

  // Insert acute after the vowel base at nucleusStart (before any combining marks already there)
  // Remove any existing accent marks first (already stripped), so just add acute.
  chars.splice(nucleusStart+1, 0, combining.acute);
  return nfc(chars.join(''));
}

function classify(word, treatCompound){
  const clean = word.trim();
  if(!clean) return {ok:false, msg:"Type a Greek word first."};

  const syll = syllabifyRough(clean).count;
  const isEinos = endsWithNormalized(clean, 'εινος') || endsWithNormalized(clean, 'ινος');
  const isOnos = endsWithNormalized(clean, 'ονος');

  let rule = null;
  let target = null;

  if(isEinos){
    if(treatCompound){
      rule = "-εινος (compound) → proparoxytone (like εὔξεινος)";
      target = 3;
    } else {
      if(syll > 2){
        rule = "-εινος (simple, >2 syllables) → oxytone";
        target = 1;
      } else {
        rule = "-εινος (≤2 syllables): rule not covered here";
        target = 1;
      }
    }
  } else if(isOnos){
    if(syll > 2){
      rule = "-ονος (>2 syllables) → proparoxytone";
      target = 3;
    } else {
      rule = "-ονος (≤2 syllables): rule not covered here";
      target = 2;
    }
  } else {
    rule = "No matching ending (-εινος / -ονος) detected; still can place a playful accent.";
    target = (syll >= 3 ? 3 : (syll === 2 ? 2 : 1));
  }

  const accented = placeAcute(clean, target);
  const label = target === 1 ? "oxytone" : (target === 2 ? "paroxytone" : "proparoxytone");

  return {
    ok:true,
    input: clean,
    stripped: stripAllDiacritics(clean),
    syllables: syll,
    ending: isEinos ? "-εινος" : (isOnos ? "-ονος" : "(other)"),
    rule,
    label,
    output: accented,
    target
  };
}

function renderResult(res, showSyll){
  if(!res.ok){
    $('#out').innerHTML = `<span class="tag bad">${escapeHtml(res.msg)}</span>`;
    return;
  }

  const tagClass = (res.ending === "(other)") ? "warn" : "good";
  const syllLine = showSyll ? `<div class="k">Syllables (rough)</div><div class="v">${res.syllables} <span class="badge">heuristic</span></div>` : "";

  $('#out').innerHTML = `
    <div class="kv">
      <div class="k">Input</div><div class="v"><span class="mono">${escapeHtml(res.input)}</span></div>
      <div class="k">Ending</div><div class="v">${escapeHtml(res.ending)} <span class="tag ${tagClass}">${escapeHtml(res.label)}</span></div>
      ${syllLine}
      <div class="k">Rule used</div><div class="v">${escapeHtml(res.rule)}</div>
      <div class="k">Toy output</div><div class="v"><span class="mono" style="font-size:18px">${escapeHtml(res.output)}</span></div>
    </div>
    <hr />
    <div class="sub">Tip: toggle “treat as compound” to see how εὔξεινος flips the accent.</div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

const sampleBank = [
  {w:"φαεινος", compound:false, note:"simple -εινος"},
  {w:"σκοτεινος", compound:false, note:"simple -εινος"},
  {w:"αλγεινος", compound:false, note:"simple -εινος"},
  {w:"βορεινος", compound:false, note:"simple -εινος"},
  {w:"ταπεινος", compound:false, note:"simple -εινος"},
  {w:"ελεεινος", compound:false, note:"simple -εινος"},
  {w:"ορεινος", compound:false, note:"simple -εινος"},
  {w:"ποθεινος", compound:false, note:"simple -εινος"},
  {w:"φωτεινος", compound:false, note:"simple -εινος"},
  {w:"ευξεινος", compound:true, note:"compound -εινος"},
  {w:"Μυκονος", compound:false, note:"-ονος"},
  {w:"Δωνεττινος", compound:false, note:"ethnic -ινος"},
  {w:"Αμοργινος", compound:false, note:"ethnic -ινος"},
  {w:"λαρινος", compound:false, note:"mentioned as oxytone like ἀληθινός"},
];

function pickRandom(){
  return sampleBank[Math.floor(Math.random()*sampleBank.length)];
}

function renderExamples(){
  const ex = [];
  for(let i=0;i<3;i++){
    const s = pickRandom();
    const res = classify(s.w, s.compound);
    ex.push(`
      <div class="ex">
        <div class="w"><span class="mono">${escapeHtml(s.w)}</span></div>
        <div class="meta">Hint: ${escapeHtml(s.note)} · toggle compound: <strong>${s.compound?"on":"off"}</strong></div>
        <div class="meta">Toy guess: <span class="mono">${escapeHtml(res.output)}</span> <span class="tag good">${escapeHtml(res.label)}</span></div>
      </div>
    `);
  }
  $('#examples').innerHTML = ex.join('');
}

function analyzeFromUI(){
  const text = $('#inp').value;
  const words = tokenizeGreekWords(text);
  const treatCompound = $('#chkCompound').checked;
  const showSyll = $('#chkShowSyll').checked;

  if(words.length === 0){
    renderResult({ok:false, msg:"Please enter a Greek word (letters only is best)."});
    return;
  }

  // If phrase, analyze first Greek-looking token
  const w = words[0];
  const res = classify(w, treatCompound);
  renderResult(res, showSyll);
}

$('#btnAnalyze').addEventListener('click', analyzeFromUI);
$('#btnClear').addEventListener('click', () => { $('#inp').value=''; $('#out').innerHTML=''; $('#inp').focus(); });
$('#btnRandom').addEventListener('click', () => {
  const s = pickRandom();
  $('#inp').value = s.w;
  $('#chkCompound').checked = !!s.compound;
  analyzeFromUI();
  renderExamples();
});
$('#inp').addEventListener('keydown', (e) => {
  if(e.key === 'Enter') analyzeFromUI();
});

// initial
renderExamples();
$('#inp').value = "ευξεινος";
$('#chkCompound').checked = true;
analyzeFromUI();

