:root{
  --bg:#0f1220;
  --card:#171a2b;
  --card2:#14172a;
  --text:#e9ecff;
  --muted:#b7bce6;
  --line:#2a2f55;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --shadow: 0 10px 30px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%); color:var(--text); font: 15px/1.45 system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;}
.wrap{max-width:980px;margin:0 auto;padding:22px 16px 28px}
.hdr{display:flex;gap:14px;align-items:flex-start;justify-content:space-between;margin-bottom:14px}
h1{font-size:20px;margin:0 0 6px;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.card{background:linear-gradient(180deg, var(--card) 0%, var(--card2) 100%); border:1px solid var(--line); border-radius:14px; padding:14px 14px 12px; box-shadow:var(--shadow); margin:12px 0}
.card h2{font-size:16px;margin:0 0 8px}
.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:10px 0}
.lbl{min-width:220px;color:var(--muted)}
.inp{flex:1;min-width:260px; padding:10px 12px; border-radius:12px; border:1px solid var(--line); background:#0c0f1f; color:var(--text); outline:none; font-size:16px}
.inp:focus{border-color:rgba(125,211,252,.7); box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btns{display:flex;gap:10px;flex-wrap:wrap}
.btn{padding:9px 12px;border-radius:12px;border:1px solid var(--line); background:#0c0f1f;color:var(--text); cursor:pointer}
.btn:hover{border-color:rgba(167,139,250,.7)}
.btn.primary{background:linear-gradient(180deg, rgba(125,211,252,.18), rgba(167,139,250,.14)); border-color:rgba(125,211,252,.35)}
.tog{display:flex;gap:14px;flex-wrap:wrap;align-items:center;color:var(--muted)}
.chk{display:flex;gap:8px;align-items:center;user-select:none}
.out{margin-top:10px; padding:12px; border-radius:12px; border:1px dashed rgba(125,211,252,.35); background:rgba(12,15,31,.65)}
.kv{display:grid;grid-template-columns: 160px 1fr; gap:6px 12px; align-items:baseline}
.k{color:var(--muted)}
.v{color:var(--text)}
