.tag{display:inline-block; padding:2px 8px; border-radius:999px; font-size:12px; margin-left:8px; border:1px solid transparent}
.tag.good{background:rgba(52,211,153,.12); border-color:rgba(52,211,153,.35); color:#bff7df}
.tag.warn{background:rgba(251,191,36,.12); border-color:rgba(251,191,36,.35); color:#ffe7b0}
.tag.bad{background:rgba(251,113,133,.12); border-color:rgba(251,113,133,.35); color:#ffd0d8}
.help{margin-top:10px; border:1px solid var(--line); border-radius:12px; padding:10px 12px; background:rgba(255,255,255,.03)}
.help summary{cursor:pointer; color:var(--accent)}
.helpBody{color:var(--muted)}
.examples{display:flex;flex-wrap:wrap;gap:10px;margin-top:10px}
.ex{flex:1;min-width:220px; border:1px solid var(--line); border-radius:12px; padding:10px 12px; background:rgba(12,15,31,.55)}
.ex .w{font-size:18px; letter-spacing:.2px}
.ex .meta{color:var(--muted); font-size:13px; margin-top:4px}
.ftr{margin-top:10px;color:var(--muted);font-size:12.5px}
.note{opacity:.95}
.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace}
hr{border:0;border-top:1px solid var(--line); margin:10px 0}
@media (max-width:560px){
  .kv{grid-template-columns: 1fr}
  .lbl{min-width:unset}
}

